1	import { Component, inject, signal } from '@angular/core';
2	import { ActivatedRoute, Router } from '@angular/router';
3	import { HttpErrorResponse } from '@angular/common/http';
4	import { forkJoin } from 'rxjs';
5	
6	import { EventsApiService } from '../../core/api/events-api.service';
7	import { BookingsApiService } from '../../core/api/bookings-api.service';
8	import { EventDetail } from '../../core/api/event-detail';
9	import { SeatMap } from '../../core/api/seat-map';
10	import { SeatMapGrid } from './seat-map/seat-map';
11	import { PriceSummary } from './price-summary/price-summary';
12	import { BookingForm } from './booking-form/booking-form';
13	import { BookingSelectionService } from './booking-selection.service';
14	
15	@Component({
16	  selector: 'app-booking',
17	  imports: [SeatMapGrid, PriceSummary, BookingForm],
18	  providers: [BookingSelectionService],
19	  templateUrl: './booking.html',
20	  styleUrl: './booking.scss'
21	})
22	export class BookingPage {
23	  private readonly route = inject(ActivatedRoute);
24	  private readonly router = inject(Router);
25	  private readonly eventsApi = inject(EventsApiService);
26	  private readonly bookingsApi = inject(BookingsApiService);
27	  private readonly selection = inject(BookingSelectionService);
28	
29	  readonly seatMap = signal<SeatMap | null>(null);
30	  readonly event = signal<EventDetail | null>(null);
31	  readonly loading = signal(true);
32	  readonly notFound = signal(false);
33	  readonly loadError = signal(false);
34	  readonly submitting = signal(false);
35	  readonly submitError = signal<string | null>(null);
36	
37	  private eventId = 0;
38	
39	  constructor() {
40	    const id = Number(this.route.snapshot.paramMap.get('id'));
41	    if (!Number.isInteger(id) || id > 2147483647) {
42	      this.loading.set(false);
43	      this.notFound.set(true);
44	      return;
45	    }
46	    this.eventId = id;
47	
48	    forkJoin({
49	      seatMap: this.eventsApi.getSeatMap(id),
50	      event: this.eventsApi.getEvent(id)
51	    }).subscribe({
52	      next: ({ seatMap, event }) => {
53	        this.seatMap.set(seatMap);
54	        this.event.set(event);
55	        this.selection.setPriceCategories(event.preiskategorien);
56	        this.loading.set(false);
57	      },
58	      error: (err: HttpErrorResponse) => {
59	        this.loading.set(false);
60	        if (err.error?.code === 'EVENT_NOT_FOUND') {
61	          this.notFound.set(true);
62	        } else {
63	          this.loadError.set(true);
64	        }
65	      }
66	    });
67	  }
68	
69	  onFormSubmitted(daten: { name: string; email: string }): void {
70	    const positionen = this.selection.selectedSeats().map(seat => ({
71	      rowLabel: seat.rowLabel,
72	      columnNumber: seat.columnNumber,
73	      priceCategoryId: seat.priceCategoryId as number // Button nur aktiv, wenn allSelectedSeatsHaveCategory() true ist
74	    }));
75	
76	    this.submitting.set(true);
77	    this.submitError.set(null);
78	
79	    this.bookingsApi
80	      .createBooking({ eventId: this.eventId, name: daten.name, email: daten.email, positionen })
81	      .subscribe({
82	        next: booking => {
83	          this.router.navigate(['/buchungen', booking.reference], { state: { booking } });
84	        },
85	        error: () => {
86	          this.submitting.set(false);
87	          this.submitError.set('Die Buchung konnte nicht abgeschlossen werden. Bitte versuchen Sie es erneut.');
88	        }
89	      });
90	  }
91	}
